"use strict";(self.webpackChunkmy_docs=self.webpackChunkmy_docs||[]).push([["841"],{4281(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/nationmc/docs/Welcome","label":"Welcome","docId":"Welcome","unlisted":false},{"type":"link","href":"/nationmc/docs/Start","label":"\u{1F680} Getting Started","docId":"Start","unlisted":false},{"type":"link","href":"/nationmc/docs/Economy","label":"\u{1F4B2} Economy & Taxes","docId":"Economy","unlisted":false},{"type":"link","href":"/nationmc/docs/Town","label":"\u{1F3F0} Town Guide","docId":"Town","unlisted":false},{"type":"link","href":"/nationmc/docs/Quarters","label":"\u{1F3E2} Quarters","docId":"Quarters","unlisted":false},{"type":"link","href":"/nationmc/docs/Claiming-Land","label":"\u{1F7E9} Claiming Land","docId":"Claiming-Land","unlisted":false},{"type":"link","href":"/nationmc/docs/Renting","label":"\u{1F3E0} Rental System","docId":"Renting","unlisted":false},{"type":"link","href":"/nationmc/docs/Nation","label":"\u{1F30E} Nation Guide","docId":"Nation","unlisted":false},{"type":"link","href":"/nationmc/docs/Shops","label":"\u{1F6D2} Shops","docId":"Shops","unlisted":false},{"type":"link","href":"/nationmc/docs/Teleporting","label":"\u{1F573}\uFE0F Teleporting","docId":"Teleporting","unlisted":false},{"type":"link","href":"/nationmc/docs/Automation","label":"\u2699\uFE0F Automation","docId":"Automation","unlisted":false},{"type":"link","href":"/nationmc/docs/Weapons","label":"\u{1F4A5} Weapons","docId":"Weapons","unlisted":false},{"type":"link","href":"/nationmc/docs/Prestige","label":"\u{1F451} Prestige","docId":"Prestige","unlisted":false},{"type":"link","href":"/nationmc/docs/Rules","label":"Server Rules","docId":"Rules","unlisted":false}]},"docs":{"Automation":{"id":"Automation","title":"Automation","description":"Tired of manual grinding and endless mining? We use the premium version of Minetorio to bring deep, satisfying automation to the server. Build massive factories, set up intricate resource processing lines, and automate the creation of literally anything you want. From automated quarries to complex item crafters, let the machines do the work while you focus on empire-building.","sidebar":"tutorialSidebar"},"Claiming-Land":{"id":"Claiming-Land","title":"How to claim land","description":"Land is divided into claims. One claim is exactly 16x16 blocks and perfectly lines up with Minecraft chunks.","sidebar":"tutorialSidebar"},"Economy":{"id":"Economy","title":"Economy & Taxes","description":"The economy is the heartbeat of NationMC. We use chest shops for player-run shops, paired with our custom NationMC Treasury & Tax Engine. Taxes are here to battle inflation and for many more reasons (which we will get into below).","sidebar":"tutorialSidebar"},"Nation":{"id":"Nation","title":"Nation Guide","description":"Create a nation","sidebar":"tutorialSidebar"},"Prestige":{"id":"Prestige","title":"Prestige","description":"In the cutthroat, geopolitical world of NationMC, wealth isn\u2019t just about what is sitting inside your vault, it\u2019s about what you show the world. The Prestige system is your ultimate way to flex your power and command respect. Climb the social ladder from a humble citizen to a tier X Elite and let your chat presence do the talking. Once you buy a Prestige tier, you own it forever. Even if you lose your town, go bankrupt, or get the [Homeless] tag, your Prestige prefix will remain attached to your name. A tier X will stay a legend forever!","sidebar":"tutorialSidebar"},"Quarters":{"id":"Quarters","title":"Quarters","description":"Quarters extends the functionality of towns and plots to allow the creation of apartments. Standard plots are restricted to a simple grid-based system that requires allowing and restricting permissions of an entire chunk. Quarters can instead allow for dynamically sized cuboids in which permissions can be edited.","sidebar":"tutorialSidebar"},"Renting":{"id":"Renting","title":"Rental System","description":"Don\'t have enough money to buy your own property yet? With our custom rental system, players can rent apartments, plots, and other properties throughout the world. New players are homeless by default and will have a Homeless] prefix in the chat. Once you rent/buy a property or plot the [Homeless] prefix will disappear and your [income tax will go from 45% to 35%. More info on taxes here.","sidebar":"tutorialSidebar"},"Rules":{"id":"Rules","title":"Server Rules","description":"Welcome to the rules page! Server rules are needed to ensure a fun and fair gameplay experience for everyone. Feel free to contact staff if you have any questions about the rules.","sidebar":"tutorialSidebar"},"Shops":{"id":"Shops","title":"Shops","description":"Introduction","sidebar":"tutorialSidebar"},"Start":{"id":"Start","title":"Getting Started","description":"NationMC takes place on a breathtaking 1:500 scale Earth map. At the heart of this world lies the biggest, most immersive, and realistic city ever built in Minecraft, featuring completely custom textures and awe-inspiring architecture.","sidebar":"tutorialSidebar"},"Teleporting":{"id":"Teleporting","title":"How to teleport","description":"You can teleport to your own town, towns within your nation, capitals of allied nations, and your bed.","sidebar":"tutorialSidebar"},"Town":{"id":"Town","title":"Town guide","description":"The essentials","sidebar":"tutorialSidebar"},"Weapons":{"id":"Weapons","title":"Weapons","description":"NationMC isn\'t just about building; it\'s about warfare and survival. We have heavily modified the vanilla experience to include deep RPG mechanics. We use custom firearms, tactical reloads, unique melee weapons, and advanced combat physics. Prepare for intense, skill-based PvP!","sidebar":"tutorialSidebar"},"Welcome":{"id":"Welcome","title":"Welcome","description":"Welcome to NationMC, a deeply immersive, player-driven geopolitical survival server. Here, you aren\'t just surviving, you are building empires, managing economies, fighting wars, and climbing the social ladder.","sidebar":"tutorialSidebar"}}}}')}}]);